-- anotoki_translations 002 - the anotoki library's own words, under its namespace anotoki.
--
-- The words the library's modules show on every site: its UI kit's (the top bar, the language and theme
-- switches, dialogs, notifications, form fields, page numbers) and its status page's.
-- anotoki-lib's php/resources/library-words.json holds them - the Angular half's built-in words are made
-- from the same file, and a test of the library holds this file to it.
--
-- A key's description is the library's, and is written again whenever a library migration carries it.
-- A key's strings are the site's once it has any: they are written here only for a library key that has
-- no string at all. So a site that took a key over before this file ran - with its own words, maybe with
-- a language left blank on purpose - keeps them, and so does an owner's rewording.
--
-- Released with anotoki-lib 0.3.0, and never edited once released: a change is a new file.

INSERT INTO translation_keys (name, description) VALUES
    ('anotoki.language.label', 'The anotoki library''s language switcher: the small heading above the languages on offer, and the accessible name of that group. The languages themselves are shown in their own names and are not strings. No placeholders.'),
    ('anotoki.language.button', 'The anotoki library''s language switcher: the accessible name of its button, which shows only the current language''s code ("SK"). {name}: that language in its own name ("Slovenčina"), shown as it is. {code}: the code the button shows - keep it in, for somebody who speaks to the computer names the button by what it shows (WCAG 2.5.3, Label in Name). Placeholders: {name}, {code}.'),
    ('anotoki.language.notLoaded', 'The anotoki library''s language switcher: said when the words of the language chosen there could not be fetched; the page stays in the language it was in. No placeholders.'),
    ('anotoki.language.notSaved', 'The anotoki library''s language switcher: said to somebody signed in when the language chosen there could not be saved to their anotoki account (the IAM out of reach, the sign-in ended); the page stays in it until it is loaded again. Not said for a language the account does not offer - that one is the site''s own choice. No placeholders.'),
    ('anotoki.siteStatus.updatingTitle', 'The anotoki library''s status page, while a database update waits (shown to everybody but the site''s ADMIN): its heading. No placeholders.'),
    ('anotoki.siteStatus.updatingText', 'The anotoki library''s status page, while a database update waits: the sentence under its heading. The page asks again by itself and reloads once the site is back. No placeholders.'),
    ('anotoki.siteStatus.unavailableTitle', 'The anotoki library''s status page, while the site cannot reach its database: its heading. No placeholders.'),
    ('anotoki.siteStatus.unavailableText', 'The anotoki library''s status page, while the site cannot reach its database: the sentence under its heading. The page asks again by itself. It speaks to the reader: a site that addresses its readers formally words it its own way. No placeholders.'),
    ('anotoki.siteStatus.notSetUpTitle', 'The anotoki library''s status page, on a site that was never set up: its heading. No placeholders.'),
    ('anotoki.siteStatus.notSetUpText', 'The anotoki library''s status page, on a site that was never set up: the sentence under its heading, above the button to the setup page. No placeholders.'),
    ('anotoki.siteStatus.openSetup', 'The anotoki library''s status page, on a site that was never set up: the button that opens its setup page. No placeholders.'),
    ('anotoki.siteStatus.tryAgain', 'The anotoki library''s status page: the button that asks the site again at once, instead of waiting for the page to ask by itself. No placeholders.'),
    ('anotoki.siteStatus.signIn', 'The anotoki library''s status page, while a database update waits and nobody is signed in: the quiet link to sign in, which is how the site''s ADMIN gets to the update. No placeholders.'),
    ('anotoki.ui.close', 'The anotoki library''s dialogs and side panels: the accessible name (and tooltip) of the button with an X that closes one. No placeholders.'),
    ('anotoki.ui.dismiss', 'The anotoki library''s notifications (the short messages in a corner of the page): the accessible name (and tooltip) of the button with an X that puts one away. No placeholders.'),
    ('anotoki.ui.notifications', 'The anotoki library''s notifications: the name screen readers give the corner of the page where they appear. No placeholders.'),
    ('anotoki.ui.cancel', 'The anotoki library''s "Are you sure?" question: the button that answers no, where the page does not word it its own way. No placeholders.'),
    ('anotoki.ui.confirm', 'The anotoki library''s "Are you sure?" question: the button that answers yes, where the page does not word it its own way. No placeholders.'),
    ('anotoki.ui.retry', 'The anotoki library''s box for something that could not be loaded: the button that asks again, where the page does not word it its own way. No placeholders.'),
    ('anotoki.ui.optional', 'The anotoki library''s form fields: the small word after the label of a field that may stay empty, in small letters. No placeholders.'),
    ('anotoki.ui.loading', 'The anotoki library''s spinner: what a screen reader hears while something loads (and what it says beside it, where it says anything). No placeholders.'),
    ('anotoki.ui.showPassword', 'The anotoki library''s password field: the accessible name (and tooltip) of the eye button while the password is hidden. No placeholders.'),
    ('anotoki.ui.hidePassword', 'The anotoki library''s password field: the accessible name (and tooltip) of the eye button while the password is shown. No placeholders.'),
    ('anotoki.ui.copy', 'The anotoki library''s copy button: its words, where the page gives it none of its own. No placeholders.'),
    ('anotoki.ui.copied', 'The anotoki library''s copy button: its words for a moment after it copied. No placeholders.'),
    ('anotoki.ui.copyToClipboard', 'The anotoki library''s copy button that shows only an icon: its accessible name and tooltip. No placeholders.'),
    ('anotoki.ui.copiedToClipboard', 'The anotoki library''s copy button: what a screen reader is told once the text is copied. No placeholders.'),
    ('anotoki.ui.copyFailed', 'The anotoki library''s copy button: said when the browser would not copy (no permission, a page not served over https), so the reader copies the text by hand. No placeholders.'),
    ('anotoki.ui.qrCode', 'The anotoki library''s QR code: the accessible name of the picture, where the page gives it none of its own. No placeholders.'),
    ('anotoki.ui.or', 'The anotoki library: the small word on the line between two ways of doing the same thing (one way of signing in, or the other), in small letters. No placeholders.'),
    ('anotoki.ui.pages', 'The anotoki library''s page numbers under a long list: the accessible name of that row of buttons. No placeholders.'),
    ('anotoki.ui.previous', 'The anotoki library''s page numbers under a long list: the button to the page before. No placeholders.'),
    ('anotoki.ui.next', 'The anotoki library''s page numbers under a long list: the button to the page after. No placeholders.'),
    ('anotoki.ui.range', 'The anotoki library''s page numbers under a long list: which of its items are shown. {first}: the first one shown, {last}: the last one shown, {total}: how many there are. Placeholders: {first}, {last}, {total}.'),
    ('anotoki.ui.pageOf', 'The anotoki library''s page numbers under a long list: where in the list the reader is. {page}: the page shown, {pages}: how many pages there are. Placeholders: {page}, {pages}.'),
    ('anotoki.ui.nothingToShow', 'The anotoki library''s page numbers under a long list: said instead of the items shown while the list is empty. No placeholders.'),
    ('anotoki.topbar.skipToContent', 'The anotoki library''s top bar: the link that shows on the first press of Tab and takes the keyboard past the bar to the page itself. No placeholders.'),
    ('anotoki.topbar.sections', 'The anotoki library''s top bar: the name screen readers give the row of the site''s own links (its sections), where the site gives it none of its own. No placeholders.'),
    ('anotoki.topbar.phoneMenu', 'The anotoki library''s top bar on a narrow screen: the accessible name of the button that opens the menu holding the site''s links. No placeholders.'),
    ('anotoki.topbar.menuButton', 'The anotoki library''s top bar: the accessible name of the round button with the person''s initials, which opens their menu. {name}: the person''s name, as their anotoki account has it. Placeholders: {name}.'),
    ('anotoki.topbar.menu', 'The anotoki library''s top bar: the name screen readers give the person''s menu itself. No placeholders.'),
    ('anotoki.topbar.roleAdmin', 'The anotoki library''s top bar: the person''s role, under their name at the top of their menu, when they are the site''s administrator. No placeholders.'),
    ('anotoki.topbar.roleEditor', 'The anotoki library''s top bar: the person''s role, under their name at the top of their menu, when they are one of the site''s editors. No placeholders.'),
    ('anotoki.topbar.account', 'The anotoki library''s top bar: the item of the person''s menu that opens their account at anotoki (their profile, password and sign-ins) in a new tab. "anotoki" is the name of the accounts, never translated. No placeholders.'),
    ('anotoki.topbar.admin', 'The anotoki library''s top bar: the item of the person''s menu that opens the site''s admin panel. No placeholders.'),
    ('anotoki.topbar.signIn', 'The anotoki library''s top bar: the button that signs in, while nobody is signed in. No placeholders.'),
    ('anotoki.topbar.signOut', 'The anotoki library''s top bar: the last item of the person''s menu, which signs them out. No placeholders.'),
    ('anotoki.topbar.saving', 'The anotoki library''s top bar: said in place of "Sign in" or "Sign out" while what was changed last is still being saved, and the item waits for it. No placeholders.'),
    ('anotoki.theme.label', 'The anotoki library''s theme switch (light, dark, as the device is set): its small heading, and the accessible name of the group. No placeholders.'),
    ('anotoki.theme.light', 'The anotoki library''s theme switch: the light look. No placeholders.'),
    ('anotoki.theme.dark', 'The anotoki library''s theme switch: the dark look. No placeholders.'),
    ('anotoki.theme.auto', 'The anotoki library''s theme switch: the look that follows the device''s own setting. No placeholders.'),
    ('anotoki.theme.autoHint', 'The anotoki library''s theme switch: the tooltip that says what the automatic look is. No placeholders.'),
    ('anotoki.theme.notSaved', 'The anotoki library''s theme switch: said to somebody signed in when the look chosen there could not be saved to their anotoki account; the page shows the account''s own again. No placeholders.')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description;

